import React, { useEffect, useRef, useState } from 'react';
import { Box, Button, Typography } from '@mui/material';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { DEMO_VENUES, DemoVenue } from '../data/venues';
import type { RefillStation } from '../data/stations';
import { useRealm, RealmPortal } from '../contexts/RealmContext';
import { usePresence } from '../contexts/PresenceContext';
import { useThemeMode, GlacerThemeMode } from '../contexts/ThemeModeContext';
import { loadFriends } from '../utils/friends';
import { personVisibleToPlayer } from '../utils/presence';
import { placeTagsText, venueFeelWord } from '../utils/placeTags';
import { elementColor, elementEmoji } from '../utils/navitarArt';

// STROLL 3D MAP (Round 12, Eddie 2026-11-17: "Build it — Round 12:
// 3D map view in Stroll… Yeah, with real streets").
//
// A third Stroll view beside the 3D scene and the 2D World Map: the
// REAL streets around the player, tilted into 3D with extruded
// buildings — the same MapLibre GL stack Eddie test-drove in the
// standalone World Map prototype on 2026-11-16 and praised for its
// smooth feel. This component is React.lazy-loaded from Stroll, so
// maplibre-gl ships in its own chunk and costs nothing for players
// who never open the view. Only one Stroll view is ever mounted at
// a time (the scene and this map are both WebGL — the app already
// manages Safari's WebGL context cap carefully; same discipline).
//
// STYLES — real street geometry AND readable street labels:
//   Light → CARTO Voyager GL (full-colour streets, cased roads,
//           street-name labels — the legible CARTO style)
//   Dark  → CARTO dark-matter GL (same real geometry, dark palette)
// The R11.1 lesson is law here: minimal near-white styles (the
// positron/light_all family) are BANNED — streets and labels must
// read clearly, which is exactly why Voyager replaces the
// prototype's positron for Light. Both styles are built on the
// same "protomaps" vector source (carto.streets schema), so the
// buildings layer below ports unchanged between them.
//
// BUILDINGS — ported verbatim from the prototype's FIXED config
// (the CARTO style-schema fix caught pre-ship on 2026-11-16):
// source "protomaps", source-layer "buildings", height coalescing
// height → render_height → 12, inserted below the first text
// symbol layer so street labels stay on top of the extrusions.
//
// GLACER LAYERS — the same data and the same honesty as RealmMap
// (the 2D World Map), never a parallel dataset:
//   - DEMO_VENUES + RealmContext portals, labelled demo the same
//     way the 2D map labels them.
//   - Presence is HEAT GLOW ONLY (privacy law): one soft blob per
//     venue, sized by the same visibility-respecting people count
//     the 2D map uses. Never an individual stranger pin.
//   - Friend pins only under the 2D map's permission model: the
//     person is your friend AND not invisible — fanned around
//     their venue by the same slot offsets.
//   - The player + the active-navitar companion, trailing a step
//     behind exactly like the 2D map's CompanionMarker (fixed
//     ~64px screen gap, eased at 0.22 per 120ms tick).
//
// LIVE POSITION — the same geolocation watch pattern as RealmMap
// (10 m jitter guard; the position is never stored or sent). The
// camera follows the player while follow is on; a drag turns
// follow off until Recenter. WALK TRAINING: accepted GPS travel
// feeds the SAME stroll distance ref the 3D scene feeds (1 real
// metre = 3 stroll units, the scene's GPS_SCALE), so Stroll's
// accrual interval pays the identical placeholder rate in this
// view (+5 XP / +1 bond per 25 units). Fixes closer than the
// jitter guard earn nothing (idle earns nothing), and a single
// jump over TELEPORT_M is treated as a GPS glitch/teleport —
// the position updates but no distance is banked.

// Shared with WorldMap3D (Round 21): the style pair, the buildings
// layer and the marker-shell helpers below are THE MapLibre core
// for every GLACER 3D map — exported so the World Map's 3D view
// renders from the same code, not a divergent copy.
export const STYLE_URLS: Record<GlacerThemeMode, string> = {
  light: 'https://basemaps.cartocdn.com/gl/voyager-gl-style/style.json',
  dark: 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',
};

// Same home base as RealmMap's LA_CENTER.
const LA_CENTER: [number, number] = [-118.44, 34.1];
const ENTRY_PITCH = 58;
const GPS_SCALE = 3; // 1 real metre = 3 stroll units (StrollScene)
const JITTER_M = 10; // RealmMap's watchPosition guard
const TELEPORT_M = 250;
// Companion gap: the 2D map's COMPANION_GAP_PX is 64px centre to
// centre; each axis gets gap / √2 (southeast, down-right on screen).
const COMPANION_OFFSET_PX = 64 / Math.SQRT2;

export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function metresBetween(aLat: number, aLng: number, bLat: number, bLng: number): number {
  const dLat = (bLat - aLat) * 110540;
  const dLon = (bLng - aLng) * 111320 * Math.cos((aLat * Math.PI) / 180);
  return Math.hypot(dLat, dLon);
}

// The prototype's buildings layer, verbatim (fixed config), with
// the fill colour following the app's palette like the prototype's
// DARK switch did.
export function addBuildingsLayer(map: maplibregl.Map, dark: boolean) {
  try {
    if (map.getLayer('glacer-buildings')) return;
    const layers = map.getStyle()?.layers ?? [];
    let labelLayerId: string | undefined;
    for (const layer of layers) {
      if (
        layer.type === 'symbol' &&
        (layer as maplibregl.SymbolLayerSpecification).layout?.['text-field']
      ) {
        labelLayerId = layer.id;
        break;
      }
    }
    map.addLayer(
      {
        id: 'glacer-buildings',
        type: 'fill-extrusion',
        source: 'protomaps',
        'source-layer': 'buildings',
        filter: ['>=', ['coalesce', ['get', 'layer'], 0], 0],
        minzoom: 14,
        paint: {
          'fill-extrusion-color': dark ? '#274b5e' : '#b9d2dc',
          'fill-extrusion-height': ['coalesce', ['get', 'height'], ['get', 'render_height'], 12],
          'fill-extrusion-base': [
            'coalesce',
            ['get', 'min_height'],
            ['get', 'render_min_height'],
            0,
          ],
          'fill-extrusion-opacity': 0.85,
        },
      } as maplibregl.LayerSpecification,
      labelLayerId
    );
  } catch {
    /* tilt still works without building extrusions */
  }
}

export function markerShell(size: number, ring: string, bg: string): HTMLDivElement {
  const el = document.createElement('div');
  el.style.cssText =
    `width:${size}px;height:${size}px;border-radius:50%;border:3px solid ${ring};` +
    `background:${bg};box-shadow:0 4px 14px rgba(0,0,0,0.4);display:flex;` +
    'align-items:center;justify-content:center;overflow:hidden;cursor:pointer;';
  return el;
}

export function markerLabel(text: string, color: string): HTMLDivElement {
  const el = document.createElement('div');
  el.textContent = text;
  el.style.cssText =
    `text-align:center;font-size:10px;font-weight:bold;color:${color};` +
    'text-shadow:0 1px 3px rgba(0,0,0,0.8);margin-top:2px;white-space:nowrap;';
  return el;
}

export function wrapMarker(pin: HTMLDivElement, label: HTMLDivElement): HTMLDivElement {
  const wrap = document.createElement('div');
  wrap.style.cssText = 'display:flex;flex-direction:column;align-items:center;';
  wrap.appendChild(pin);
  wrap.appendChild(label);
  return wrap;
}

export interface StrollMap3DCompanion {
  name: string;
  element: string;
  imageUrl?: string | null;
}

const StrollMap3D: React.FC<{
  companion: StrollMap3DCompanion | null;
  distanceRef: React.MutableRefObject<number>;
  // The owner's Home Station (Round 36.9 Part 9) — owner-only,
  // planted on-device; null for everyone else.
  homeStation?: RefillStation | null;
  onHomeStationClick?: (station: RefillStation) => void;
}> = ({ companion, distanceRef, homeStation = null, onHomeStationClick }) => {
  const { mode } = useThemeMode();
  const { portals } = useRealm();
  const { businessContactIds } = usePresence();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const modeRef = useRef<GlacerThemeMode>(mode);
  const [follow, setFollow] = useState(true);
  const followRef = useRef(true);
  const [hasFix, setHasFix] = useState(false);

  // Live refs the map callbacks read (they outlive any one render).
  const playerPosRef = useRef<[number, number]>(LA_CENTER); // [lng, lat]
  const lastFixRef = useRef<{ lat: number; lng: number } | null>(null);
  const firstFixRef = useRef(false);
  const playerMarkerRef = useRef<maplibregl.Marker | null>(null);
  const companionMarkerRef = useRef<maplibregl.Marker | null>(null);
  const companionPosRef = useRef<[number, number] | null>(null);
  const companionTargetRef = useRef<[number, number] | null>(null);
  const companionRef = useRef<StrollMap3DCompanion | null>(companion);
  const distanceRefRef = useRef(distanceRef);
  distanceRefRef.current = distanceRef;

  // ---- main init (once) ----
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const map = new maplibregl.Map({
      container,
      style: STYLE_URLS[modeRef.current],
      center: LA_CENTER,
      zoom: 13.5,
      pitch: ENTRY_PITCH,
      bearing: 0,
      attributionControl: { compact: true },
    });
    mapRef.current = map;
    map.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), 'bottom-right');
    map.touchPitch.enable();
    map.dragRotate.enable();

    const applyBuildings = () => addBuildingsLayer(map, modeRef.current === 'dark');
    map.on('load', applyBuildings);
    map.on('style.load', applyBuildings);
    map.on('dragstart', () => {
      followRef.current = false;
      setFollow(false);
    });

    // ----- GLACER layers (same data as RealmMap) -----
    const friendIds = loadFriends();

    // Heat glow — one blob per venue with a visible crowd, sized
    // exactly like the 2D map's heatIcon (90 + 26/person, cap 190).
    DEMO_VENUES.forEach((venue: DemoVenue) => {
      const density = venue.people.filter(p =>
        personVisibleToPlayer(p, { businessContactIds, friendIds })
      ).length;
      if (density <= 0) return;
      const size = Math.min(190, 90 + density * 26);
      const el = document.createElement('div');
      el.style.cssText =
        `width:${size}px;height:${size}px;border-radius:50%;pointer-events:none;` +
        'background:radial-gradient(circle, rgba(64,224,138,0.4) 0%, rgba(64,224,138,0.16) 45%, rgba(64,224,138,0) 70%);';
      new maplibregl.Marker({ element: el }).setLngLat([venue.lng, venue.lat]).addTo(map);
    });

    // Demo venues.
    DEMO_VENUES.forEach(venue => {
      const pin = markerShell(38, '#ffffff', elementColor(venue.element));
      pin.style.fontSize = '19px';
      pin.textContent = elementEmoji(venue.element);
      const el = wrapMarker(pin, markerLabel(venue.name, '#ffffff'));
      // Round 28 (sim §26): NO PUBLIC COUNTS — this popup used to
      // print the venue's raw people count ("N here", not even
      // visibility-filtered). It now shows the FEEL word banded
      // from the same visibility-respecting density as the heat
      // glow above, plus the venue's place tags (§§28–30).
      const density = venue.people.filter(p =>
        personVisibleToPlayer(p, { businessContactIds, friendIds })
      ).length;
      const tags = placeTagsText(venue);
      new maplibregl.Marker({ element: el })
        .setLngLat([venue.lng, venue.lat])
        .setPopup(
          new maplibregl.Popup({ offset: 26, closeButton: false }).setHTML(
            `<strong>${elementEmoji(venue.element)} ${escapeHtml(venue.name)}</strong><br/>` +
              `Demo venue · ${escapeHtml(venue.tagline)}<br/>` +
              `${venueFeelWord(density)} tonight · check in from the World Map` +
              (tags ? `<br/>🏷 ${escapeHtml(tags)}` : '')
          )
        )
        .addTo(map);
    });

    // Portals (RealmContext — the same list the 2D map draws).
    portals.forEach((portal: RealmPortal) => {
      const pin = markerShell(34, '#ffd76a', elementColor(portal.type));
      pin.style.fontSize = '17px';
      pin.textContent = elementEmoji(portal.type);
      const el = wrapMarker(pin, markerLabel(portal.name, '#ffd76a'));
      new maplibregl.Marker({ element: el })
        .setLngLat([portal.location.lng, portal.location.lat])
        .setPopup(
          new maplibregl.Popup({ offset: 24, closeButton: false }).setHTML(
            `<strong>${elementEmoji(portal.type)} ${escapeHtml(portal.name)}</strong><br/>` +
              `Portal · Lv. ${portal.level} · demo portal`
          )
        )
        .addTo(map);
    });

    // Friend pins — the ONLY individual people markers, under the
    // 2D map's exact rule (friend + not invisible) and slot fan.
    DEMO_VENUES.forEach(venue => {
      venue.people
        .filter(p => friendIds.includes(p.id) && p.visibility !== 'invisible')
        .forEach((person, slot) => {
          const pin = markerShell(40, '#7be2ae', '#0a2531');
          if (person.navitarImage) {
            const img = document.createElement('img');
            img.src = person.navitarImage;
            img.alt = '';
            img.style.cssText = 'width:100%;height:100%;object-fit:cover;';
            pin.appendChild(img);
          } else {
            pin.style.fontSize = '20px';
            pin.textContent = elementEmoji(person.navitarElement);
          }
          const el = wrapMarker(pin, markerLabel(person.name, '#7be2ae'));
          new maplibregl.Marker({ element: el })
            .setLngLat([
              venue.lng + 0.0022 * (Math.floor(slot / 2) * 2 - 1) + 0.0016,
              venue.lat + 0.0016 * ((slot % 2) * 2 - 1),
            ])
            .setPopup(
              new maplibregl.Popup({ offset: 26, closeButton: false }).setHTML(
                `<strong>${escapeHtml(person.name)}</strong> — your friend<br/>` +
                  `${escapeHtml(person.navitarName)} (Lv. ${person.navitarLevel} · ${person.navitarElement})`
              )
            )
            .addTo(map);
        });
    });

    // Player marker — stands at home base until the first GPS fix,
    // exactly like the 2D map's playerPos fallback.
    const playerEl = document.createElement('div');
    playerEl.style.cssText =
      'width:18px;height:18px;border-radius:50%;background:#1a86e8;border:3px solid #fff;' +
      'box-shadow:0 0 0 6px rgba(26,134,232,0.25),0 2px 8px rgba(0,0,0,0.4)';
    playerMarkerRef.current = new maplibregl.Marker({ element: playerEl })
      .setLngLat(LA_CENTER)
      .setPopup(
        new maplibregl.Popup({ offset: 18, closeButton: false }).setHTML(
          '<strong>You are here</strong>'
        )
      )
      .addTo(map);

    // Companion trailing target: the player projected ~64px
    // southeast on screen, unprojected — the 2D map's own math.
    const updateCompanionTarget = () => {
      const p = map.project(maplibregl.LngLat.convert(playerPosRef.current));
      const ll = map.unproject([p.x + COMPANION_OFFSET_PX, p.y + COMPANION_OFFSET_PX]);
      companionTargetRef.current = [ll.lng, ll.lat];
      if (!companionPosRef.current) {
        companionPosRef.current = [ll.lng, ll.lat];
        companionMarkerRef.current?.setLngLat(companionPosRef.current);
      }
    };
    map.on('moveend', updateCompanionTarget);
    map.on('zoomend', updateCompanionTarget);
    updateCompanionTarget();

    // Trailing ease — the 2D map's 0.22-per-120ms walk toward the
    // target; goes quiet on arrival (no state churn: markers are
    // imperative DOM here, so an idle tick costs nothing).
    const trail = window.setInterval(() => {
      const cur = companionPosRef.current;
      const tgt = companionTargetRef.current;
      const marker = companionMarkerRef.current;
      if (!cur || !tgt || !marker) return;
      const dLng = tgt[0] - cur[0];
      const dLat = tgt[1] - cur[1];
      if (Math.abs(dLng) < 1e-7 && Math.abs(dLat) < 1e-7) return;
      const next: [number, number] = [cur[0] + dLng * 0.22, cur[1] + dLat * 0.22];
      companionPosRef.current = next;
      marker.setLngLat(next);
      container.dataset.companionPos = `${next[1]},${next[0]}`;
    }, 120);

    // ----- live position (RealmMap's watch pattern) -----
    let watchId: number | null = null;
    if ('geolocation' in navigator && navigator.geolocation.watchPosition) {
      watchId = navigator.geolocation.watchPosition(
        pos => {
          const { latitude, longitude } = pos.coords;
          const last = lastFixRef.current;
          if (last) {
            const m = metresBetween(last.lat, last.lng, latitude, longitude);
            if (m < JITTER_M) return; // jitter — marker doesn't tremble, no distance
            if (m <= TELEPORT_M) {
              // Real travel pays walk training at the scene's rate.
              distanceRefRef.current.current += m * GPS_SCALE;
            }
            // m > TELEPORT_M: a glitch/teleport — position updates below, nothing banked.
          }
          lastFixRef.current = { lat: latitude, lng: longitude };
          playerPosRef.current = [longitude, latitude];
          playerMarkerRef.current?.setLngLat([longitude, latitude]);
          container.dataset.playerPos = `${latitude},${longitude}`;
          setHasFix(true);
          updateCompanionTarget();
          if (!firstFixRef.current) {
            firstFixRef.current = true;
            if (followRef.current) {
              map.flyTo({
                center: [longitude, latitude],
                zoom: 15.5,
                pitch: ENTRY_PITCH,
                duration: 1200,
              });
            }
          } else if (followRef.current) {
            map.easeTo({ center: [longitude, latitude], duration: 600 });
          }
        },
        () => {},
        { enableHighAccuracy: true, maximumAge: 2000 }
      );
    }

    return () => {
      window.clearInterval(trail);
      if (watchId !== null && 'geolocation' in navigator) {
        navigator.geolocation.clearWatch(watchId);
      }
      map.remove();
      mapRef.current = null;
      playerMarkerRef.current = null;
      companionMarkerRef.current = null;
      companionPosRef.current = null;
      companionTargetRef.current = null;
      lastFixRef.current = null;
      firstFixRef.current = false;
    };
    // Init once: portals/friend data are the demo sets the 2D map
    // mounts with; theme changes are handled by the effect below.
  }, []);

  // ---- theme follow: swap the GL style, re-add buildings ----
  useEffect(() => {
    modeRef.current = mode;
    const map = mapRef.current;
    if (!map) return;
    map.setStyle(STYLE_URLS[mode]);
    // The 'style.load' listener from init re-adds the buildings.
  }, [mode]);

  // ---- companion marker sync (the pick is the single source of
  // truth — swapping in the header/Navidex updates the marker) ----
  useEffect(() => {
    companionRef.current = companion;
    const map = mapRef.current;
    if (!map) return;
    if (!companion) {
      companionMarkerRef.current?.remove();
      companionMarkerRef.current = null;
      companionPosRef.current = null;
      return;
    }
    const build = () => {
      const pin = markerShell(52, elementColor(companion.element), '#0a2531');
      if (companion.imageUrl) {
        const img = document.createElement('img');
        img.src = companion.imageUrl;
        img.alt = '';
        img.style.cssText = 'width:100%;height:100%;object-fit:cover;';
        pin.appendChild(img);
      } else {
        pin.style.fontSize = '24px';
        pin.textContent = elementEmoji(companion.element);
      }
      const el = wrapMarker(pin, markerLabel(companion.name, '#ffffff'));
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat(companionPosRef.current ?? companionTargetRef.current ?? LA_CENTER)
        .setPopup(
          new maplibregl.Popup({ offset: 28, closeButton: false }).setHTML(
            `<strong>${elementEmoji(companion.element)} ${escapeHtml(companion.name)}</strong><br/>Your companion`
          )
        )
        .addTo(map);
      companionMarkerRef.current = marker;
    };
    if (companionMarkerRef.current) {
      companionMarkerRef.current.remove();
      companionMarkerRef.current = null;
    }
    build();
  }, [companion?.name, companion?.element, companion?.imageUrl]);

  // ---- Home Station marker (Round 36.9 Part 9): owner-only,
  // planted on-device by the Stroll page; synced here like the
  // companion marker. Tapping it opens the station card on the
  // page (the same collect flow as the World Map). ----
  const homeMarkerRef = useRef<maplibregl.Marker | null>(null);
  const homeClickRef = useRef(onHomeStationClick);
  homeClickRef.current = onHomeStationClick;
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    homeMarkerRef.current?.remove();
    homeMarkerRef.current = null;
    if (!homeStation) return;
    const pin = markerShell(40, '#ffffff', '#009688');
    pin.style.fontSize = '22px';
    pin.textContent = '🧪';
    const el = wrapMarker(pin, markerLabel(homeStation.name, '#ffffff'));
    el.dataset.mapMarker = 'station';
    el.dataset.stationId = homeStation.id;
    el.addEventListener('click', () => homeClickRef.current?.(homeStation));
    homeMarkerRef.current = new maplibregl.Marker({ element: el })
      .setLngLat([homeStation.lng, homeStation.lat])
      .setPopup(
        new maplibregl.Popup({ offset: 26, closeButton: false }).setHTML(
          `<strong>🧪 ${escapeHtml(homeStation.name)}</strong><br/>` +
            `Your refill station — only you can see it.<br/>` +
            `Tap the station card below to collect potions.`
        )
      )
      .addTo(map);
  }, [homeStation]);

  const recenter = () => {
    const map = mapRef.current;
    if (!map) return;
    followRef.current = true;
    setFollow(true);
    map.flyTo({
      center: playerPosRef.current,
      zoom: 15.5,
      pitch: ENTRY_PITCH,
      bearing: 0,
      duration: 1000,
    });
  };

  return (
    <Box
      sx={{
        width: '100%',
        height: 560,
        position: 'relative',
        borderRadius: '16px',
        overflow: 'hidden',
        bgcolor: '#0a2531',
      }}
    >
      <div
        ref={containerRef}
        data-testid="stroll-map3d"
        style={{ position: 'absolute', inset: 0 }}
      />
      <Box sx={{ position: 'absolute', left: 12, top: 12, zIndex: 2 }}>
        <Button
          size="small"
          variant={follow && hasFix ? 'contained' : 'outlined'}
          onClick={recenter}
          sx={{ bgcolor: follow && hasFix ? undefined : 'rgba(6,24,33,0.65)', color: '#e8f6fb' }}
        >
          📍 Recenter
        </Button>
      </Box>
      <Box
        sx={{
          position: 'absolute',
          left: 12,
          bottom: 12,
          zIndex: 2,
          px: 1.25,
          py: 0.5,
          borderRadius: 999,
          bgcolor: 'rgba(6, 24, 33, 0.55)',
          pointerEvents: 'none',
          maxWidth: '78%',
        }}
      >
        <Typography variant="caption" sx={{ color: '#e8f6fb' }}>
          3D streets — demo venues &amp; portals, heat glow for people nearby (never pins)
        </Typography>
      </Box>
    </Box>
  );
};

export default StrollMap3D;
